mapper.select:
SELECT
  COALESCE(SUM(CASE WHEN time_hour >= #{yesterday} AND time_hour < #{today}
    THEN revenue_amount ELSE 0 END), 0) AS yesterdayIncome,
  COALESCE(SUM(CASE WHEN time_hour >= #{sevenDays}
    THEN revenue_amount ELSE 0 END), 0) AS sevenDayIncome,
  COALESCE(SUM(CASE WHEN time_hour >= #{thirtyDays}
    THEN revenue_amount ELSE 0 END), 0) AS thirtyDayIncome,
  COALESCE(SUM(revenue_amount), 0) AS totalIncome
FROM scx_adx_hourly_report
WHERE 1=1
AND advertiser_id = #{advertiserId}
